begin;

-- Länder
update countries set name = '{"de":"Deutschland","en":"Germany"}'::jsonb, mica_authority = 'BaFin (mit Bundesbank)', mica_transition_ended = '2025-12-31'::date, ad_label = 'Werbung', tax_summary = '{"de":"Gewinne aus dem Verkauf von Kryptowerten sind steuerpflichtig, wenn zwischen Kauf und Verkauf höchstens ein Jahr liegt; danach sind sie grundsätzlich steuerfrei. Auch das Bezahlen mit Krypto gilt als Verkauf, das gilt ebenso für Stablecoins. Liegt der Gesamtgewinn aus privaten Veräußerungsgeschäften im Jahr unter 1.000 €, bleibt er steuerfrei (Freigrenze, kein Freibetrag).","en":"Gains from selling crypto-assets are taxable if no more than one year passes between purchase and sale; after that they are generally tax-free. Paying with crypto also counts as a sale, including stablecoins. If total gains from private disposals stay below €1,000 per year, they remain tax-free (an exemption limit, not an allowance)."}'::jsonb, tax_uncertain = false, tax_source_url = 'https://www.bundesfinanzministerium.de/Content/DE/Downloads/BMF_Schreiben/Steuerarten/Einkommensteuer/2025-03-06-einzelfragen-kryptowerte.html', tax_verified_at = null where code = 'DE';
update countries set name = '{"de":"Österreich","en":"Austria"}'::jsonb, mica_authority = 'FMA', mica_transition_ended = '2025-12-31'::date, ad_label = 'Werbung', tax_summary = '{"de":"Für Kryptowerte, die ab dem 1. März 2021 gekauft wurden, gelten grundsätzlich 27,5 % auf realisierte Gewinne, unabhängig von der Haltedauer. Der Tausch Krypto gegen Krypto ist dabei steuerneutral, das Bezahlen von Waren oder Dienstleistungen nicht. Für ältere Bestände gelten abweichende Regeln.","en":"For crypto-assets bought from 1 March 2021, realised gains are generally taxed at 27.5%, regardless of holding period. Swapping crypto for crypto is tax-neutral, paying for goods or services is not. Different rules apply to older holdings."}'::jsonb, tax_uncertain = false, tax_source_url = 'https://findok.bmf.gv.at/findok/volltext?segmentId=78321e88-b64d-4007-b22b-858b930c515f', tax_verified_at = null where code = 'AT';
update countries set name = '{"de":"Frankreich","en":"France"}'::jsonb, mica_authority = 'AMF (ACPR für Institute)', mica_transition_ended = '2026-07-01'::date, ad_label = 'Publicité', tax_summary = '{"de":"Verkäufe und Zahlungen mit Krypto werden 2026 in der Regel mit 31,4 % pauschal besteuert (12,8 % Einkommensteuer plus 18,6 % Sozialabgaben). Der Tausch Krypto gegen Krypto ist aufgeschoben. Liegen die Verkaufserlöse eines Haushalts im Jahr bei höchstens 305 €, bleiben sie steuerfrei; der Gewinn wird anteilig über das gesamte Portfolio berechnet.","en":"Sales and payments with crypto are generally taxed at a flat 31.4% in 2026 (12.8% income tax plus 18.6% social charges). Crypto-to-crypto swaps are deferred. If a household''s sale proceeds stay at or below €305 per year, they are tax-free; the gain is calculated proportionally across the whole portfolio."}'::jsonb, tax_uncertain = false, tax_source_url = 'https://bofip.impots.gouv.fr/export/pdf/12857', tax_verified_at = null where code = 'FR';
update countries set name = '{"de":"Spanien","en":"Spain"}'::jsonb, mica_authority = 'CNMV', mica_transition_ended = '2025-12-30'::date, ad_label = 'Publicidad', tax_summary = '{"de":"Gewinne aus Verkauf, Tausch (auch Krypto gegen Krypto) und Bezahlen mit Krypto werden mit gestaffelten Sätzen von 19 % bis 30 % besteuert. Eine steuerfreie Haltefrist gibt es nicht. Wer Kryptowerte im Ausland verwahrt, muss ab 50.000 € zusätzlich eine Informationserklärung (Modell 721) abgeben.","en":"Gains from selling, swapping (including crypto to crypto) and paying with crypto are taxed at progressive rates from 19% to 30%. There is no tax-free holding period. Holding crypto abroad requires an additional information return (form 721) from €50,000."}'::jsonb, tax_uncertain = false, tax_source_url = 'https://sede.agenciatributaria.gob.es/Sede/ayuda/manuales-videos-folletos/manuales-practicos/irpf-2025/c11-ganancias-perdidas-patrimoniales/ganancias-perdidas-patrimoniales-derivadas-transmisiones-elementos/monedas-virtuales/compra-venta-monedas-virtuales.html', tax_verified_at = null where code = 'ES';
update countries set name = '{"de":"Italien","en":"Italy"}'::jsonb, mica_authority = 'Consob / Banca d''Italia', mica_transition_ended = '2026-06-30'::date, ad_label = 'Pubblicità', tax_summary = '{"de":"Seit 2026 gelten grundsätzlich 33 % auf Krypto-Gewinne im Privatvermögen, ohne Freigrenze und ohne Haltefrist. Das Bezahlen mit Krypto ist eine steuerlich relevante Verwendung. Zusätzlich kann eine jährliche Abgabe von 0,2 % auf den Wert gehaltener Kryptowerte anfallen; für Altbestände gibt es Übergangsregeln.","en":"Since 2026, crypto gains in private assets are generally taxed at 33%, with no exemption limit and no holding period. Paying with crypto is a tax-relevant use. An annual levy of 0.2% on the value of crypto held may also apply; transition rules exist for older holdings."}'::jsonb, tax_uncertain = true, tax_source_url = 'https://www.agenziaentrate.gov.it/portale/documents/d/guest/pf2_istruzioni_2026', tax_verified_at = null where code = 'IT';
update countries set name = '{"de":"Niederlande","en":"Netherlands"}'::jsonb, mica_authority = 'AFM (DNB prudenziell)', mica_transition_ended = '2025-06-30'::date, ad_label = 'Advertentie', tax_summary = '{"de":"Privates Kryptovermögen fällt in der Regel in Box 3: Besteuert wird ein pauschal angenommener Ertrag auf das Vermögen, nicht jeder einzelne Verkauf. Eine Kartenzahlung löst deshalb normalerweise keine eigene Gewinnsteuer aus. Box 3 wird derzeit umgebaut, ein niedrigerer tatsächlicher Ertrag kann nachgewiesen werden.","en":"Private crypto holdings usually fall under Box 3: a deemed return on wealth is taxed, not each individual sale. A card payment therefore normally triggers no separate gains tax. Box 3 is currently being reformed, and a lower actual return can be demonstrated."}'::jsonb, tax_uncertain = true, tax_source_url = 'https://www.belastingdienst.nl/wps/wcm/connect/nl/box-3/content/berekening-box-3-inkomen-2026', tax_verified_at = null where code = 'NL';
update countries set name = '{"de":"Malta","en":"Malta"}'::jsonb, mica_authority = 'MFSA', mica_transition_ended = '2026-07-01'::date, ad_label = 'Advert', tax_summary = '{"de":"Die Besteuerung hängt stark von der Einordnung ab: Gewinne aus häufigem Handel können als Einkommen bis 35 % besteuert werden, Gewinne aus als Kapitalanlage gehaltenen Coins können außerhalb der Kapitalgewinnsteuer liegen. Eine pauschale Aussage für Kartenzahlungen ist nicht möglich.","en":"Taxation depends heavily on classification: gains from frequent trading can be taxed as income up to 35%, gains from coins held as a capital investment may fall outside capital gains tax. A general statement for card payments is not possible."}'::jsonb, tax_uncertain = true, tax_source_url = 'https://mtca.gov.mt/docs/default-source/documents/business-tax/mtca-guidelines---tax-treatment-of-dlt-assets.pdf', tax_verified_at = null where code = 'MT';
update countries set name = '{"de":"Zypern","en":"Cyprus"}'::jsonb, mica_authority = 'CySEC (Central Bank of Cyprus für EMT/EMI)', mica_transition_ended = '2026-07-01'::date, ad_label = 'Διαφήμιση', tax_summary = '{"de":"Seit 1. Januar 2026 gilt für Gewinne aus der Veräußerung von Kryptowerten ein eigener Satz von 8 %. Auch das Bezahlen von Waren und Dienstleistungen gilt als Veräußerung. Verluste lassen sich grundsätzlich nur mit Krypto-Gewinnen desselben Jahres verrechnen; die Verwaltungspraxis ist noch jung.","en":"Since 1 January 2026, gains from disposing of crypto-assets are taxed at a separate rate of 8%. Paying for goods and services also counts as a disposal. Losses can generally only be offset against crypto gains of the same year; administrative practice is still new."}'::jsonb, tax_uncertain = true, tax_source_url = 'https://www.harneys.com/our-blogs/regulatory/a-new-era-for-cyprus-taxation-the-key-insights-of-the-2026-cyprus-tax-reform/', tax_verified_at = null where code = 'CY';

