insert into providers (slug, name, website_url, data_controller_country, data_controller_note, data_residency_note, kyc_note, protection_note, trustpilot_domain, is_published) values ('bitpanda', 'Bitpanda', 'https://www.bitpanda.com', 'AT', '{"de":"Plattform: jeweilige Bitpanda-Gesellschaft (Österreich). Kartendaten: Kartenherausgeber Contis als eigener Verantwortlicher.","en":"Platform: the relevant Bitpanda entity (Austria). Card data: card issuer Contis as separate controller."}'::jsonb, '{"de":"Kartendaten auf Servern in der EU und im Vereinigten Königreich; Übermittlung nach UK über Standardvertragsklauseln.","en":"Card data on servers in the EU and the UK; transfer to the UK under standard contractual clauses."}'::jsonb, null, '{"de":"Kryptowerte getrennt vom Firmenvermögen verwahrt. Karten-E-Geld abgesichert, aber nicht von der Einlagensicherung erfasst.","en":"Crypto-assets held separately from company assets. Card e-money safeguarded but not covered by deposit insurance."}'::jsonb, 'bitpanda.com', true)
